/**
 * TypeScript Advanced Types — Utility Types and Patterns
 */

// ---- Mapped Types ----
type Readonly<T> = { readonly [K in keyof T]: T[K] };
type Partial<T>  = { [K in keyof T]?: T[K] };
type Required<T> = { [K in keyof T]-?: T[K] };
type Pick<T, K extends keyof T> = { [P in K]: T[P] };
type Omit<T, K extends keyof T> = Pick<T, Exclude<keyof T, K>>;

// Custom: make specific keys optional
type PartialBy<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;

interface User {
  id: number;
  name: string;
  email: string;
  role: 'admin' | 'user';
}

type CreateUser = Omit<User, 'id'>;                  // no id on create
type UpdateUser = PartialBy<User, 'name' | 'email'>; // partial update

// ---- Conditional Types ----
type IsArray<T> = T extends any[] ? true : false;
type Flatten<T> = T extends Array<infer U> ? U : T;
type Awaited<T> = T extends Promise<infer U> ? Awaited<U> : T;

type A = Flatten<number[]>;       // number
type B = Flatten<string[][]>;     // string[]
type C = Awaited<Promise<string>>; // string

// ---- Template Literal Types ----
type EventName = `on${Capitalize<string>}`;
type ApiRoute = `/api/${string}`;
type CSSProperty = `${string}-${string}`;

type HttpMethod = 'GET' | 'POST' | 'PUT' | 'DELETE';
type Endpoint = `${HttpMethod} /api/${string}`;
// 'GET /api/users', 'POST /api/orders', etc.

// ---- Discriminated Unions ----
type Success<T> = { status: 'success'; data: T };
type Failure    = { status: 'error';   error: string; code: number };
type Result<T>  = Success<T> | Failure;

function handleResult<T>(result: Result<T>): T | null {
  switch (result.status) {
    case 'success': return result.data;
    case 'error':   console.error(result.error); return null;
  }
}

// ---- Infer in Conditional Types ----
type ReturnType<T extends (...args: any) => any> =
  T extends (...args: any) => infer R ? R : never;

type Parameters<T extends (...args: any) => any> =
  T extends (...args: infer P) => any ? P : never;

type Head<T extends any[]> = T extends [infer H, ...any[]] ? H : never;
type Tail<T extends any[]> = T extends [any, ...infer T] ? T : never;

// ---- Builder with Type Safety ----
class TypedEventEmitter<Events extends Record<string, any>> {
  private listeners: Partial<{ [K in keyof Events]: ((data: Events[K]) => void)[] }> = {};

  on<K extends keyof Events>(event: K, listener: (data: Events[K]) => void) {
    (this.listeners[event] ??= []).push(listener);
    return this;
  }

  emit<K extends keyof Events>(event: K, data: Events[K]) {
    this.listeners[event]?.forEach(fn => fn(data));
  }
}

interface AppEvents {
  login:   { userId: number; timestamp: Date };
  logout:  { userId: number };
  error:   { message: string; code: number };
}

const emitter = new TypedEventEmitter<AppEvents>();
emitter.on('login', ({ userId }) => console.log(`User ${userId} logged in`));
emitter.emit('login', { userId: 123, timestamp: new Date() }); // type-safe!
// emitter.emit('login', { wrongProp: true }); // TS ERROR ✅

/**
 * Node.js Performance Patterns
 */

// 1. Connection Pooling
const { Pool } = require('pg');
const pool = new Pool({
  host: process.env.DB_HOST,
  database: process.env.DB_NAME,
  max: 20,              // max connections in pool
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});

async function query(sql, params) {
  const client = await pool.connect();
  try {
    return await client.query(sql, params);
  } finally {
    client.release();  // return to pool!
  }
}

// 2. Batch database operations
async function insertMany(records) {
  // BAD: N separate INSERT statements
  // for (const r of records) await db.query('INSERT ...', [r]);

  // GOOD: Single INSERT with multiple values
  const values = records.map((r, i) => `($${i*3+1},$${i*3+2},$${i*3+3})`).join(',');
  const flat = records.flatMap(r => [r.id, r.name, r.email]);
  await pool.query(`INSERT INTO users (id,name,email) VALUES ${values}`, flat);
}

// 3. Worker Threads for CPU-intensive tasks
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

if (isMainThread) {
  function runWorker(data) {
    return new Promise((resolve, reject) => {
      const worker = new Worker(__filename, { workerData: data });
      worker.on('message', resolve);
      worker.on('error', reject);
    });
  }
  // Usage: await runWorker({ numbers: [1,2,...,1000000] });
} else {
  // Runs in worker thread (doesn't block event loop)
  const result = workerData.numbers.reduce((a, b) => a + b, 0);
  parentPort.postMessage(result);
}

// 4. Caching with stale-while-revalidate
const cache = new Map();

async function getWithSWR(key, fetchFn, ttl = 60000) {
  const hit = cache.get(key);
  const now = Date.now();
  if (hit) {
    if (now - hit.ts < ttl) return hit.data;  // fresh
    // Stale: return old data, refresh in background
    fetchFn().then(data => cache.set(key, { data, ts: Date.now() }));
    return hit.data;
  }
  const data = await fetchFn();
  cache.set(key, { data, ts: now });
  return data;
}

// 5. Rate limiting middleware
const rateLimit = new Map();

function rateLimitMiddleware(windowMs = 60000, max = 100) {
  return (req, res, next) => {
    const key = req.ip;
    const now = Date.now();
    const window = rateLimit.get(key) || { count: 0, start: now };

    if (now - window.start > windowMs) {
      rateLimit.set(key, { count: 1, start: now });
    } else {
      window.count++;
      if (window.count > max) {
        return res.status(429).json({ error: 'Too many requests', retryAfter: Math.ceil((window.start + windowMs - now) / 1000) });
      }
      rateLimit.set(key, window);
    }
    next();
  };
}

// 6. Graceful shutdown
process.on('SIGTERM', async () => {
  console.log('SIGTERM received. Closing connections...');
  server.close(async () => {
    await pool.end();      // drain DB pool
    await redis.quit();    // close Redis
    process.exit(0);
  });
  setTimeout(() => process.exit(1), 10000); // force exit after 10s
});

module.exports = { query, insertMany, getWithSWR, rateLimitMiddleware };

import { useState, useEffect, useRef, useCallback, useMemo } from 'react';

// 1. useFetch — data fetching with loading/error states
function useFetch<T>(url: string, options?: RequestInit) {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const controller = new AbortController();
    setLoading(true);
    fetch(url, { ...options, signal: controller.signal })
      .then(res => { if (!res.ok) throw new Error(`HTTP ${res.status}`); return res.json(); })
      .then(setData)
      .catch(err => { if (err.name !== 'AbortError') setError(err.message); })
      .finally(() => setLoading(false));
    return () => controller.abort();
  }, [url]);

  return { data, loading, error };
}

// 2. useLocalStorage — persisted state
function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    try {
      const item = localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch { return initialValue; }
  });

  const setStoredValue = useCallback((newValue: T | ((val: T) => T)) => {
    const resolved = typeof newValue === 'function' ? (newValue as (v: T) => T)(value) : newValue;
    setValue(resolved);
    localStorage.setItem(key, JSON.stringify(resolved));
  }, [key, value]);

  return [value, setStoredValue] as const;
}

// 3. useDebounce — debounce rapidly changing values
function useDebounce<T>(value: T, delay: number): T {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);
  return debounced;
}

// 4. useClickOutside — close dropdowns/modals
function useClickOutside(callback: () => void) {
  const ref = useRef<HTMLElement>(null);
  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) callback();
    };
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [callback]);
  return ref;
}

// 5. useInterval — declarative setInterval
function useInterval(callback: () => void, delay: number | null) {
  const savedCallback = useRef(callback);
  useEffect(() => { savedCallback.current = callback; });
  useEffect(() => {
    if (delay === null) return;
    const id = setInterval(() => savedCallback.current(), delay);
    return () => clearInterval(id);
  }, [delay]);
}

// 6. usePrevious — track previous value
function usePrevious<T>(value: T): T | undefined {
  const ref = useRef<T>();
  useEffect(() => { ref.current = value; });
  return ref.current;
}

// 7. useMediaQuery — responsive hooks
function useMediaQuery(query: string): boolean {
  const [matches, setMatches] = useState(() => window.matchMedia(query).matches);
  useEffect(() => {
    const mq = window.matchMedia(query);
    const handler = (e: MediaQueryListEvent) => setMatches(e.matches);
    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, [query]);
  return matches;
}

// 8. useAsync — run async functions with state tracking
function useAsync<T>(asyncFn: () => Promise<T>, deps: any[] = []) {
  const [state, setState] = useState<{ data: T | null; loading: boolean; error: string | null }>({
    data: null, loading: false, error: null
  });
  const execute = useCallback(async () => {
    setState({ data: null, loading: true, error: null });
    try {
      const data = await asyncFn();
      setState({ data, loading: false, error: null });
    } catch (err: any) {
      setState({ data: null, loading: false, error: err.message });
    }
  }, deps);
  return { ...state, execute };
}

export { useFetch, useLocalStorage, useDebounce, useClickOutside, useInterval, usePrevious, useMediaQuery, useAsync };

"""
Python dataclasses and Pydantic — Modern data modeling.
"""

from dataclasses import dataclass, field, asdict, astuple
from typing import Optional, List, ClassVar
from datetime import datetime

# ---- Dataclasses ----
@dataclass
class Point:
    x: float
    y: float

    def distance_to(self, other: 'Point') -> float:
        return ((self.x - other.x)**2 + (self.y - other.y)**2) ** 0.5

@dataclass
class Order:
    id: int
    customer: str
    items: List[str] = field(default_factory=list)
    created_at: datetime = field(default_factory=datetime.now)
    _internal: str = field(default='', repr=False)  # excluded from repr

    # Class variable (not an instance field)
    total_orders: ClassVar[int] = 0

    def __post_init__(self):
        Order.total_orders += 1
        if not self.customer:
            raise ValueError('Customer cannot be empty')

@dataclass(frozen=True)  # immutable, hashable
class Coordinate:
    lat: float
    lng: float
    # Can be used as dict key or in sets!

@dataclass(order=True)  # enables <, >, ==
class Priority:
    sort_index: int = field(init=False)
    name: str
    value: int

    def __post_init__(self):
        self.sort_index = self.value


# ---- Pydantic (validation + serialization) ----
try:
    from pydantic import BaseModel, validator, Field, EmailStr
    from pydantic import ValidationError

    class UserCreate(BaseModel):
        name: str = Field(..., min_length=2, max_length=50)
        email: str  # EmailStr if email-validator installed
        age: int = Field(..., ge=0, le=150)
        role: str = Field(default='user', regex='^(admin|user|moderator)$')
        tags: List[str] = []

        @validator('name')
        def name_must_not_contain_spaces_at_edges(cls, v):
            return v.strip()

        @validator('email')
        def email_lowercase(cls, v):
            return v.lower()

        class Config:
            # Allow feeding ORM models directly
            from_orm = True
            # Strip extra fields from input
            extra = 'ignore'

    # Usage
    try:
        user = UserCreate(name='  Alice  ', email='ALICE@EXAMPLE.COM', age=25)
        print(user.name)   # 'Alice' (validator applied)
        print(user.email)  # 'alice@example.com'
        print(user.dict()) # serialize to dict
        print(user.json()) # serialize to JSON
    except ValidationError as e:
        print(e.errors())  # list of validation errors

    # Nested models
    class Address(BaseModel):
        street: str
        city: str
        country: str = 'India'

    class UserFull(BaseModel):
        id: int
        name: str
        address: Optional[Address] = None
        created_at: datetime = Field(default_factory=datetime.now)

except ImportError:
    print('Install pydantic: pip install pydantic')


# ---- Simple usage ----
if __name__ == '__main__':
    o1 = Order(1, 'Alice', ['laptop', 'mouse'])
    o2 = Order(2, 'Bob')
    print(asdict(o1))
    print(Order.total_orders)  # 2

    p1, p2 = Point(0, 0), Point(3, 4)
    print(p1.distance_to(p2))  # 5.0

    loc = Coordinate(28.6, 77.2)
    cache = {loc: 'Delhi'}  # hashable!

/**
 * JavaScript Proxy and Reflect — Meta-programming
 * Intercept and customize object operations.
 */

// 1. Validation proxy
function createValidatedObject(target, validators) {
  return new Proxy(target, {
    set(obj, prop, value) {
      if (validators[prop] && !validators[prop](value)) {
        throw new TypeError(`Invalid value for ${String(prop)}: ${value}`);
      }
      return Reflect.set(obj, prop, value);
    }
  });
}

const user = createValidatedObject({}, {
  age: (v) => typeof v === 'number' && v >= 0 && v <= 150,
  email: (v) => typeof v === 'string' && v.includes('@'),
});
user.email = 'alice@example.com'; // ✅
// user.age = -5;  // ❌ TypeError

// 2. Observable object (Vue 3's reactivity core idea)
function reactive(target, onChange) {
  return new Proxy(target, {
    set(obj, prop, value) {
      const oldValue = obj[prop];
      const result = Reflect.set(obj, prop, value);
      if (oldValue !== value) onChange(prop, oldValue, value);
      return result;
    },
    deleteProperty(obj, prop) {
      const result = Reflect.deleteProperty(obj, prop);
      onChange(prop, obj[prop], undefined);
      return result;
    }
  });
}

const state = reactive({ count: 0 }, (key, old, next) => {
  console.log(`${key}: ${old} → ${next}`);
});
state.count++; // count: 0 → 1

// 3. Lazy loading of properties
function lazyProps(loaders) {
  return new Proxy({}, {
    get(obj, prop) {
      if (prop in obj) return obj[prop];
      if (prop in loaders) {
        obj[prop] = loaders[prop]();  // compute once
        return obj[prop];
      }
    }
  });
}

const config = lazyProps({
  db: () => ({ host: 'localhost', port: 5432 }),
  cache: () => ({ ttl: 3600 }),
});
config.db;    // computed now
config.db;    // cached, not recomputed

// 4. Array negative indexing (Python-like)
function arrayWithNegIndex(arr) {
  return new Proxy(arr, {
    get(target, prop) {
      const n = parseInt(prop);
      const idx = n < 0 ? target.length + n : n;
      return Reflect.get(target, isNaN(n) ? prop : idx);
    }
  });
}

const arr = arrayWithNegIndex([1,2,3,4,5]);
console.log(arr[-1]);  // 5 (last element)
console.log(arr[-2]);  // 4

// 5. Method chaining builder (SQL-like)
function queryBuilder(tableName) {
  const state = { table: tableName, conditions: [], cols: ['*'], lim: null };
  const handler = {
    get(target, prop) {
      if (prop === 'build') {
        return () => {
          let q = `SELECT ${state.cols.join(',')} FROM ${state.table}`;
          if (state.conditions.length) q += ` WHERE ${state.conditions.join(' AND ')}`;
          if (state.lim) q += ` LIMIT ${state.lim}`;
          return q;
        };
      }
      if (prop === 'where') return (cond) => { state.conditions.push(cond); return proxy; };
      if (prop === 'select') return (...cols) => { state.cols = cols; return proxy; };
      if (prop === 'limit') return (n) => { state.lim = n; return proxy; };
      return Reflect.get(target, prop);
    }
  };
  const proxy = new Proxy({}, handler);
  return proxy;
}

const q = queryBuilder('users').select('id','name').where('age > 18').limit(10).build();
console.log(q); // SELECT id,name FROM users WHERE age > 18 LIMIT 10

package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

// 1. WaitGroup — wait for goroutines to finish
func processItems(items []int) []int {
	results := make([]int, len(items))
	var wg sync.WaitGroup
	for i, item := range items {
		wg.Add(1)
		go func(idx, val int) {
			defer wg.Done()
			results[idx] = val * 2 // process concurrently
		}(i, item)
	}
	wg.Wait()
	return results
}

// 2. Worker Pool Pattern
func workerPool(jobs <-chan int, results chan<- int, numWorkers int) {
	var wg sync.WaitGroup
	for i := 0; i < numWorkers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for job := range jobs {
				results <- job * job // do work
			}
		}()
	}
	go func() { wg.Wait(); close(results) }()
}

// 3. Fan-out / Fan-in
func fanOut(input <-chan int, numWorkers int) []<-chan int {
	channels := make([]<-chan int, numWorkers)
	for i := range channels {
		ch := make(chan int)
		channels[i] = ch
		go func(out chan<- int) {
			for v := range input { out <- v * 2 }
			close(out)
		}(ch)
	}
	return channels
}

func fanIn(channels ...<-chan int) <-chan int {
	merged := make(chan int)
	var wg sync.WaitGroup
	for _, ch := range channels {
		wg.Add(1)
		go func(c <-chan int) { defer wg.Done(); for v := range c { merged <- v } }(ch)
	}
	go func() { wg.Wait(); close(merged) }()
	return merged
}

// 4. Pipeline Pattern
func generate(nums ...int) <-chan int {
	out := make(chan int)
	go func() { for _, n := range nums { out <- n }; close(out) }()
	return out
}

func square(in <-chan int) <-chan int {
	out := make(chan int)
	go func() { for n := range in { out <- n * n }; close(out) }()
	return out
}

// 5. Context cancellation
func longRunning(ctx context.Context) error {
	for {
		select {
		case <-ctx.Done():
			return ctx.Err() // context cancelled or deadline exceeded
		case <-time.After(100 * time.Millisecond):
			fmt.Println("working...")
		}
	}
}

// 6. Mutex for shared state
type SafeCounter struct {
	mu    sync.RWMutex
	count map[string]int
}

func (c *SafeCounter) Inc(key string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.count[key]++
}

func (c *SafeCounter) Get(key string) int {
	c.mu.RLock() // multiple goroutines can read concurrently
	defer c.mu.RUnlock()
	return c.count[key]
}

// 7. Once — run function exactly once (Singleton)
var (
	instance *SafeCounter
	once     sync.Once
)

func GetInstance() *SafeCounter {
	once.Do(func() {
		instance = &SafeCounter{count: make(map[string]int)}
	})
	return instance
}

func main() {
	// Pipeline
	for n := range square(square(generate(2, 3, 4))) {
		fmt.Println(n) // 16, 81, 256
	}

	// Context with timeout
	ctx, cancel := context.WithTimeout(context.Background(), 500*time.Millisecond)
	defer cancel()
	longRunning(ctx)
}
